from fractions import Fraction

def px(x):
    return Fraction(1, 2)

def py(y, x):
    return {(1, 1): Fraction(4, 5), (0, 1): Fraction(1, 5), (1, 0): Fraction(1, 5), (0, 0): Fraction(4, 5)}[(y, x)]

def pz(z, y):
    return {(1, 1): Fraction(3, 4), (0, 1): Fraction(1, 4), (1, 0): Fraction(1, 4), (0, 0): Fraction(3, 4)}[(z, y)]

psi = {y: sum(px(x) * py(y, x) for x in (0, 1)) for y in (0, 1)}
assert psi[0] == psi[1] == Fraction(1, 2)
marg = {z: sum(psi[y] * pz(z, y) for y in (0, 1)) for z in (0, 1)}
assert marg[1] == Fraction(1, 2)
tau = {(x, z): sum(py(y, x) * pz(z, y) for y in (0, 1)) for x in (0, 1) for z in (0, 1)}
assert tau[(1, 1)] == Fraction(13, 20) and tau[(0, 1)] == Fraction(7, 20)
assert len(tau) == 4 and len(psi) == 2
marg2 = {z: sum(px(x) * tau[(x, z)] for x in (0, 1)) for z in (0, 1)}
assert marg2[1] == Fraction(1, 2)
joint = px(1) * tau[(1, 1)]
assert joint == Fraction(13, 40)
post = joint / marg[1]
assert post == Fraction(13, 20)
assert post.numerator + post.denominator == 33
print(marg[1], post)
